SELECT g.question_id AS question_id, g.direction AS direction, a.id AS last_wrong_id, COALESCE(a.answer, '') AS last_answer, a.at AS last_at, q.kind AS kind, CASE WHEN :lang = 'ja' AND TRIM(COALESCE(q.prompt_ja, '')) <> '' THEN q.prompt_ja ELSE q.prompt_zh END AS prompt FROM (SELECT question_id, direction, mid, SUM(CASE WHEN correct = 1 AND hinted = 0 AND id > mid THEN 1 ELSE 0 END) AS good FROM (SELECT id, question_id, direction, correct, hinted, MAX(CASE WHEN correct = 0 THEN id END) OVER (PARTITION BY question_id, direction) AS mid FROM dictation_question_attempt WHERE learner = :learner AND subject_id = CAST(:subject_id AS INTEGER)) WHERE mid IS NOT NULL GROUP BY question_id, direction, mid) g JOIN dictation_question_attempt a ON a.id = g.mid JOIN dictation_question q ON q.id = g.question_id AND q.subject_id = CAST(:subject_id AS INTEGER) WHERE g.good < 2 ORDER BY a.id DESC
